INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_03','V325','阮明',3,'没问题，这些药具体怎么服用呀？','méi wèn tí， zhè xiē yào jù tǐ zěn me fú yòng ya？','Không sao, mà mấy loại thuốc này uống thế nào vậy ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_04','V325','药师',4,'都是一日三次，饭后温水服用，说明书也有标注。','dōu shì yī rì sān cì， fàn hòu wēn shuǐ fú yòng， shuō míng shū yě yǒu biāo zhù。','Đều là ngày uống ba lần, sau bữa ăn uống với nước ấm, trên tờ hướng dẫn cũng có ghi rõ đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_05','V325','阮明',5,'需要低温冷藏保存吗？','xū yào dī wēn lěng cáng bǎo cún ma？','Có cần bảo quản lạnh không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_06','V325','药师',6,'不用，常温避光存放就可以。','bù yòng， cháng wēn bì guāng cún fàng jiù kě yǐ。','Không cần đâu, để nơi nhiệt độ thường, tránh ánh sáng là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_07','V325','阮明',7,'明白了，谢谢药师！','míng bái le， xiè xiè yào shī！','Tôi hiểu rồi, cảm ơn dược sĩ nhé!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT326','S109','Hỏi bảo hiểm có chi trả loại thuốc này không',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V326','SIT326','P1','twist','ban_chinh_thuc',NULL,'国内医保仅覆盖基础刚需药品，进口药、高端特效药大多需要个人自费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_01','V326','阮明',1,'你好，我想问一下我开的这些药能不能医保报销？','nǐ hǎo， wǒ xiǎng wèn yī xià wǒ kāi de zhè xiē yào néng bù néng yī bǎo bào xiāo？','Chào bạn, tôi muốn hỏi mấy loại thuốc bác sĩ kê cho tôi có được bảo hiểm y tế chi trả không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_02','V326','工作人员',2,'我帮你查询一下药品医保目录。','wǒ bāng nǐ chá xún yī xià yào pǐn yī bǎo mù lù。','Để tôi tra giúp bạn xem thuốc có nằm trong danh mục bảo hiểm y tế không nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_03','V326','工作人员',3,'查到了，其中两款基础药可以报销，一款进口药不行。','chá dào le， qí zhōng liǎng kuǎn jī chǔ yào kě yǐ bào xiāo， yī kuǎn jìn kǒu yào bù xíng。','Tra ra rồi, trong đó có hai loại thuốc cơ bản được chi trả, còn một loại thuốc nhập khẩu thì không.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_04','V326','阮明',4,'这样啊，进口药需要全额自费是吗？','zhè yàng a， jìn kǒu yào xū yào quán é zì fèi shì ma？','Vậy à, thuốc nhập khẩu là phải tự chi trả toàn bộ đúng không?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_05','V326','工作人员',5,'对的，进口特效药不在医保报销范围内。','duì de， jìn kǒu tè xiào yào bù zài yī bǎo bào xiāo fàn wéi nèi。','Đúng vậy, thuốc đặc trị nhập khẩu không nằm trong phạm vi chi trả của bảo hiểm y tế.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_06','V326','阮明',6,'我了解了，那麻烦你分开结算吧。','wǒ liǎo jiě le， nà má fán nǐ fēn kāi jié suàn ba。','Tôi hiểu rồi, vậy phiền bạn tính riêng hai khoản đó giúp tôi nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_07','V326','工作人员',7,'没问题，我帮你区分清楚。','méi wèn tí， wǒ bāng nǐ qū fēn qīng chǔ。','Không vấn đề gì, tôi sẽ tách riêng rõ ràng cho bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT327','S109','Đặt lịch tái khám',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V327','SIT327','P1','suon_se','ban_chinh_thuc',NULL,'慢性病、短期病症恢复都需要复诊，携带既往病历是医院常规要求。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_01','V327','阮明',1,'你好，我想预约下周的复诊门诊。','nǐ hǎo， wǒ xiǎng yù yuē xià zhōu de fù zhěn mén zhěn。','Chào bạn, tôi muốn đặt lịch tái khám vào tuần sau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_02','V327','工作人员',2,'可以的，你想预约周几的时间段？','kě yǐ de， nǐ xiǎng yù yuē zhōu jǐ de shí jiān duàn？','Được ạ, bạn muốn đặt vào khung giờ ngày nào trong tuần?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_03','V327','阮明',3,'下周二下午吧，我下午没有课程安排。','xià zhōu èr xià wǔ ba， wǒ xià wǔ méi yǒu kè chéng ān pái。','Chiều thứ Ba tuần sau nhé, chiều đó tôi không có lịch học.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_04','V327','工作人员',4,'好的，已经为你预约成功。','hǎo de， yǐ jīng wèi nǐ yù yuē chéng gōng。','Vâng, tôi đã đặt lịch thành công cho bạn rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_05','V327','阮明',5,'复诊的时候需要带这次的病历本吗？','fù zhěn de shí hòu xū yào dài zhè cì de bìng lì běn ma？','Lúc tái khám tôi có cần mang theo sổ khám bệnh lần này không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_06','V327','工作人员',6,'需要的，务必携带方便医生对比恢复情况。','xū yào de， wù bì xié dài fāng biàn yī shēng duì bǐ huī fù qíng kuàng。','Cần đấy, nhất định phải mang theo để bác sĩ tiện so sánh tình trạng hồi phục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_07','V327','阮明',7,'好的，我会妥善保管，谢谢你！','hǎo de， wǒ huì tuǒ shàn bǎo guǎn， xiè xiè nǐ！','Vâng, tôi sẽ giữ cẩn thận, cảm ơn bạn!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT328','S109','Xin giấy chứng nhận nghỉ bệnh cho trường',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V328','SIT328','P1','suon_se','chinh_thuc',NULL,'国内高校只认可医院机打正规病假证明，手写证明无效，是统一考勤制度。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_01','V328','阮明',1,'医生您好，我身体不适需要请假，麻烦您开具一张病假证明。','yī shēng nín hǎo， wǒ shēn tǐ bù shì xū yào qǐng jià， má fán nín kāi jù yī zhāng bìng jià zhèng míng。','Chào bác sĩ, tôi thấy trong người không khỏe cần xin nghỉ, phiền bác sĩ viết giúp tôi giấy chứng nhận nghỉ bệnh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_02','V328','医生',2,'没问题，你需要请假休养几天？','méi wèn tí， nǐ xū yào qǐng jià xiū yǎng jǐ tiān？','Không vấn đề gì, ông/bà cần nghỉ dưỡng mấy ngày ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_03','V328','阮明',3,'我身体比较虚弱，想请假两天调整状态。','wǒ shēn tǐ bǐ jiào xū ruò， xiǎng qǐng jià liǎng tiān tiáo zhěng zhuàng tài。','Cơ thể tôi khá yếu, tôi muốn xin nghỉ hai ngày để điều chỉnh lại sức khỏe.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_04','V328','医生',4,'可以，我给你开具正规机打病假证明。','kě yǐ， wǒ gěi nǐ kāi jù zhèng guī jī dǎ bìng jià zhèng míng。','Được, tôi sẽ viết cho ông/bà giấy chứng nhận nghỉ bệnh in chính thức.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_05','V328','阮明',5,'证明上会标注就诊时间和请假时长对吧？','zhèng míng shàng huì biāo zhù jiù zhěn shí jiān hé qǐng jià shí cháng duì ba？','Trên giấy chứng nhận sẽ ghi rõ thời gian khám và số ngày nghỉ đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_06','V328','医生',6,'是的，信息齐全，学校可以直接认可。','shì de， xìn xī qí quán， xué xiào kě yǐ zhí jiē rèn kě。','Đúng vậy, thông tin đầy đủ, nhà trường có thể công nhận trực tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_07','V328','阮明',7,'太感谢医生了！','tài gǎn xiè yī shēng le！','Cảm ơn bác sĩ rất nhiều ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT329','S111','Tự giới thiệu trong buổi sinh hoạt đầu năm',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V329','SIT329','P1','suon_se','ban_chinh_thuc',NULL,'新生自我介绍简洁谦逊即可，"多多指教"是国内年轻人社交最常用的礼貌用语。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_01','V329','阮明',1,'大家好，我是阮明，一名来自越南的留学生，今年22岁。','dà jiā hǎo， wǒ shì ruǎn míng， yī míng lái zì yuè nán de liú xué shēng， jīn nián 22 suì。','Chào mọi người, mình là Nguyễn Minh, du học sinh đến từ Việt Nam, năm nay 22 tuổi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_02','V329','阮明',2,'目前就读于汉语言文学专业，非常开心加入这个集体。','mù qián jiù dú yú hàn yǔ yán wén xué zhuān yè， fēi cháng kāi xīn jiā rù zhè ge jí tǐ。','Hiện mình đang theo học ngành Ngôn ngữ và Văn học Trung Quốc, rất vui khi được gia nhập tập thể mình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_03','V329','阮明',3,'平时我喜欢读书和慢跑，性格比较随和开朗。','píng shí wǒ xǐ huān dú shū hé màn pǎo， xìng gé bǐ jiào suí hé kāi lǎng。','Bình thường mình thích đọc sách và chạy bộ, tính cách khá hòa đồng, vui vẻ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_04','V329','阮明',4,'我刚来中国，对这边的学习和生活还在适应中。','wǒ gāng lái zhōng guó， duì zhè biān de xué xí hé shēng huó hái zài shì yìng zhōng。','Mình mới sang Trung Quốc, việc học tập và sinh hoạt ở đây mình vẫn đang thích nghi dần.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_05','V329','阮明',5,'往后希望可以和各位同学友好相处，互相学习、多多指教。','wǎng hòu xī wàng kě yǐ hé gè wèi tóng xué yǒu hǎo xiāng chǔ， hù xiāng xué xí、 duō duō zhǐ jiào。','Sau này mong được hòa thuận với các bạn, cùng nhau học hỏi, mong mọi người chỉ bảo thêm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_06','V329','辅导员',6,'欢迎阮明加入我们的大家庭！','huān yíng ruǎn míng jiā rù wǒ men de dà jiā tíng！','Chào mừng Nguyễn Minh gia nhập đại gia đình của chúng ta!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_07','V329','阮明',7,'谢谢大家！','xiè xiè dà jiā！','Cảm ơn mọi người ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT330','S111','Hỏi thông tin liên hệ để giữ kết nối',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V330','SIT330','P1','suon_se','tuy_y',NULL,'微信是国内学生唯一主流沟通工具，学习通知、日常交友、小组协作均依托微信完成。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_01','V330','阮明',1,'今天认识你真的太开心了！我们可以加个微信吗？','jīn tiān rèn shí nǐ zhēn de tài kāi xīn le！ wǒ men kě yǐ jiā gè wēi xìn ma？','Hôm nay quen được bạn thật là vui quá! Mình kết bạn Wechat được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_02','V330','林溪',2,'当然可以呀，以后我们就是同班同学了。','dāng rán kě yǐ ya， yǐ hòu wǒ men jiù shì tóng bān tóng xué le。','Được chứ, sau này tụi mình là bạn cùng lớp rồi mà.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_03','V330','阮明',3,'太好了，我刚来这边，以后还要多向你请教呢。','tài hǎo le， wǒ gāng lái zhè biān， yǐ hòu hái yào duō xiàng nǐ qǐng jiào ne。','Tuyệt quá, mình mới đến đây, sau này còn phải nhờ bạn chỉ bảo nhiều đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_04','V330','林溪',4,'不用客气，我们互相帮忙、共同进步。','bù yòng kè qì， wǒ men hù xiāng bāng máng、 gòng tóng jìn bù。','Đừng khách sáo, tụi mình giúp đỡ nhau, cùng nhau tiến bộ mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_05','V330','阮明',5,'那我扫你的二维码加好友哈。','nà wǒ sǎo nǐ de èr wéi mǎ jiā hǎo yǒu hā。','Vậy để mình quét mã QR kết bạn với bạn nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_06','V330','林溪',6,'好嘞，以后常联系，有空一起学习！','hǎo lei， yǐ hòu cháng lián xì， yǒu kòng yì qǐ xué xí！','Ok nha, sau này liên lạc thường xuyên, rảnh thì học cùng nhau nhé!','AM08') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_07','V330','阮明',7,'太好啦，谢谢你！','tài hǎo la， xiè xiè nǐ！','Tuyệt quá, cảm ơn bạn nhiều nhé!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT331','S112','Mời bạn cùng lớp đi ăn',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V331','SIT331','P1','suon_se','tuy_y',NULL,'中国大学生下课常结伴去食堂就餐，主动邀约同学吃饭是很常见的社交方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_01','V331','阮明',1,'下课啦，等下要不要一起去食堂吃饭啊？','xià kè la， děng xià yào bù yào yì qǐ qù shí táng chī fàn a？','Tan học rồi, lát nữa cùng đi căng tin ăn cơm không?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_02','V331','王浩',2,'可以呀，我正愁一个人吃饭没意思呢。','kě yǐ ya， wǒ zhèng chóu yí gè rén chī fàn méi yì si ne。','Được chứ, mình đang buồn vì phải ăn một mình chán lắm đây.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_03','V331','阮明',3,'食堂今天有米线，听说味道很不错的。','shí táng jīn tiān yǒu mǐ xiàn， tīng shuō wèi dào hěn bú cuò de。','Hôm nay căng tin có bún gạo đó, nghe nói ngon lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_04','V331','王浩',4,'刚好我也想吃米线，咱们现在就走吧。','gāng hǎo wǒ yě xiǎng chī mǐ xiàn， zán men xiàn zài jiù zǒu ba。','Đúng lúc mình cũng đang thèm bún gạo, tụi mình đi luôn đi.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_05','V331','阮明',5,'行，那我收拾一下书本，马上就好。','xíng， nà wǒ shōu shí yī xià shū běn， mǎ shàng jiù hǎo。','Được, để mình thu dọn sách vở chút, xong ngay thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_06','V331','王浩',6,'没事，我在教室门口等你就行啦。','méi shì， wǒ zài jiào shì mén kǒu děng nǐ jiù xíng la。','Không sao, mình đợi bạn ở cửa lớp là được rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_07','V331','阮明',7,'太感谢啦，有同学一起吃饭热闹多了。','tài gǎn xiè la， yǒu tóng xué yì qǐ chī fàn rè nào duō le。','Cảm ơn bạn nhiều nha, có bạn cùng ăn vui hơn hẳn.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT332','S112','Từ chối lời mời một cách lịch sự',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V332','SIT332','P1','suon_se','tuy_y',NULL,'拒绝他人邀约时，中国人习惯说明合理理由并主动提出下次赴约，显得有礼貌不扫兴。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_01','V332','林晓',1,'晚上我们宿舍一起去校外吃火锅，你也来吧？','wǎn shàng wǒ men sù shè yì qǐ qù xiào wài chī huǒ guō， nǐ yě lái ba？','Tối nay ký túc xá tụi mình rủ nhau ra ngoài ăn lẩu, bạn đi cùng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_02','V332','阮明',2,'真的很谢谢你邀请我，不过我今晚不行呢。','zhēn de hěn xiè xiè nǐ yāo qǐng wǒ， bù guò wǒ jīn wǎn bù xíng ne。','Cảm ơn bạn đã rủ mình nha, nhưng tối nay mình không đi được.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_03','V332','林晓',3,'怎么啦，是有别的安排吗？','zěn me la， shì yǒu bié de ān pái ma？','Sao vậy, có việc gì khác à?','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_04','V332','阮明',4,'我要完成一篇汉语作文，明天就得提交的。','wǒ yào wán chéng yī piān hàn yǔ zuò wén， míng tiān jiù dé tí jiāo de。','Mình phải hoàn thành một bài luận tiếng Trung, mai phải nộp rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_05','V332','林晓',5,'原来是这样，学习要紧，那下次再约吧。','yuán lái shì zhè yàng， xué xí yào jǐn， nà xià cì zài yuē ba。','Ra là vậy, học hành quan trọng hơn, vậy lần sau hẹn lại nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_06','V332','阮明',6,'好，下次我一定主动找你们，实在抱歉啦。','hǎo， xià cì wǒ yí dìng zhǔ dòng zhǎo nǐ men， shí zài bào qiàn la。','Ừ, lần sau mình nhất định sẽ chủ động rủ mọi người, thật ngại quá.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_07','V332','林晓',7,'没关系，学习完早点休息。','méi guān xì， xué xí wán zǎo diǎn xiū xī。','Không sao đâu, học xong nhớ nghỉ ngơi sớm nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT333','S112','Xin lỗi vì đến muộn buổi hẹn',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V333','SIT333','P1','twist','ban_chinh_thuc',NULL,'与人线下见面迟到，中国人会主动诚恳道歉，还会主动提出买单、请客作为补偿。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_01','V333','阮明',1,'实在对不起，我路上堵车，迟到二十分钟了。','shí zài duì bù qǐ， wǒ lù shàng dǔ chē， chí dào èr shí fēn zhōng le。','Thật xin lỗi, đường tắc nên mình đến trễ hai mươi phút.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_02','V333','陈悦',2,'没事，我也刚到一会儿，不用这么愧疚。','méi shì， wǒ yě gāng dào yī huì er， bù yòng zhè me kuì jiù。','Không sao, mình cũng mới đến một chút thôi, đừng áy náy quá vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_03','V333','阮明',3,'都怪我没提前出门，让你在这里干等啊。','dōu guài wǒ méi tí qián chū mén， ràng nǐ zài zhè lǐ gàn děng a。','Tại mình không ra khỏi nhà sớm hơn, để bạn phải đợi không đâu.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_04','V333','陈悦',4,'还好，这家咖啡店座位挺多，我先点了两杯饮品。','hái hǎo， zhè jiā kā fēi diàn zuò wèi tǐng duō， wǒ xiān diǎn le liǎng bēi yǐn pǐn。','Không sao mà, quán cà phê này khá nhiều chỗ ngồi, mình gọi trước hai ly rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_05','V333','阮明',5,'太不好意思了，这杯饮品我来付钱吧。','tài bù hǎo yì sī le， zhè bēi yǐn pǐn wǒ lái fù qián ba。','Ngại quá, để mình trả tiền ly nước này nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_06','V333','陈悦',6,'不用啦，下次见面你请我就可以咯。','bù yòng la， xià cì jiàn miàn nǐ qǐng wǒ jiù kě yǐ gē。','Thôi khỏi, lần sau gặp lại bạn mời mình là được rồi.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_07','V333','阮明',7,'好，下次我一定提前半小时出门，绝不迟到。','hǎo， xià cì wǒ yí dìng tí qián bàn xiǎo shí chū mén， jué bù chí dào。','Được, lần sau mình nhất định sẽ ra khỏi nhà sớm nửa tiếng, không trễ nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT334','S112','Cảm ơn khi được giúp đỡ đặc biệt',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V334','SIT334','P1','suon_se','ban_chinh_thuc',NULL,'得到他人较大帮助后，中国人常会赠送小零食、小礼物表达谢意，不会只口头道谢。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_01','V334','阮明',1,'班长，这次真的太谢谢你帮我补办签证材料了。','bān zhǎng， zhè cì zhēn de tài xiè xiè nǐ bāng wǒ bǔ bàn qiān zhèng cái liào le。','Lớp trưởng ơi, lần này thật sự cảm ơn bạn đã giúp mình làm lại hồ sơ visa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_02','V334','周宇',2,'小事而已，留学生办理手续本来就麻烦嘛。','xiǎo shì ér yǐ， liú xué shēng bàn lǐ shǒu xù běn lái jiù má fán ma。','Chuyện nhỏ thôi mà, du học sinh làm thủ tục vốn dĩ đã phiền phức sẵn rồi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_03','V334','阮明',3,'要是没有你带路讲解，我肯定跑好多趟。','yào shì méi yǒu nǐ dài lù jiǎng jiě， wǒ kěn dìng pǎo hǎo duō tàng。','Nếu không có bạn dẫn đường và giải thích, chắc mình phải chạy đi chạy lại mấy lần.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_04','V334','周宇',4,'不用放在心上，班里同学互相帮忙是应该的。','bù yòng fàng zài xīn shàng， bān lǐ tóng xué hù xiāng bāng máng shì yīng gāi de。','Đừng để bụng làm gì, bạn bè trong lớp giúp đỡ nhau là chuyện nên làm mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_05','V334','阮明',5,'下周我买了家乡小零食，带给你尝尝吧。','xià zhōu wǒ mǎi le jiā xiāng xiǎo líng shí， dài gěi nǐ cháng cháng ba。','Tuần sau mình mua ít đồ ăn vặt quê mình, mang cho bạn thử nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_06','V334','周宇',6,'不用这么客气，能帮上忙我也很高兴。','bù yòng zhè me kè qì， néng bāng shàng máng wǒ yě hěn gāo xìng。','Không cần khách sáo vậy đâu, giúp được bạn mình cũng vui rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_07','V334','阮明',7,'一定要收下，不然我心里过意不去呢。','yí dìng yào shōu xià， bù rán wǒ xīn lǐ guò yì bù qù ne。','Nhất định phải nhận đó, không thì mình áy náy trong lòng lắm.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT335','S113','Hỏi sở thích để tìm điểm chung với bạn mới',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V335','SIT335','P1','suon_se','tuy_y',NULL,'初次认识的年轻人会通过爱好聊天，找到共同兴趣能快速拉近彼此距离。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_01','V335','阮明',1,'课余时间你平时都喜欢做什么呀？','kè yú shí jiān nǐ píng shí dōu xǐ huān zuò shén me ya？','Ngoài giờ học bạn thường thích làm gì vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_02','V335','苏雯',2,'我有空就会追剧、出门爬山，你呢？','wǒ yǒu kòng jiù huì zhuī jù、 chū mén pá shān， nǐ ne？','Rảnh là mình xem phim, rồi đi leo núi, còn bạn thì sao?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_03','V335','阮明',3,'我也很喜欢爬山，只是刚来还不熟悉周边路线。','wǒ yě hěn xǐ huān pá shān， zhǐ shì gāng lái hái bù shú xī zhōu biān lù xiàn。','Mình cũng rất thích leo núi, chỉ là mới đến nên chưa quen đường xung quanh lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_04','V335','苏雯',4,'学校附近有一座小山，周末可以一起去的。','xué xiào fù jìn yǒu yī zuò xiǎo shān， zhōu mò kě yǐ yì qǐ qù de。','Gần trường có một ngọn núi nhỏ, cuối tuần có thể đi cùng nhau đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_05','V335','阮明',5,'太棒了，我还担心找不到同好呢。','tài bàng le， wǒ hái dān xīn zhǎo bú dào tóng hào ne。','Tuyệt quá, mình còn lo không tìm được ai hợp gu chứ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_06','V335','苏雯',6,'那我们加个微信，周末约着一起出发吧。','nà wǒ men jiā gè wēi xìn， zhōu mò yuē zhe yì qǐ chū fā ba。','Vậy tụi mình kết bạn Wechat nhé, cuối tuần hẹn nhau đi luôn.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_07','V335','阮明',7,'好呀，终于找到一样爱好的朋友啦。','hǎo ya， zhōng yú zhǎo dào yī yàng ài hào de péng yǒu la。','Được đó, cuối cùng cũng tìm được người bạn cùng sở thích rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT336','S114','Đăng ký tham gia câu lạc bộ sinh viên',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V336','SIT336','P1','twist','ban_chinh_thuc',NULL,'国内高校社团统一在开学招新，多数社团有活动人数限制，需要提前登记报名。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_01','V336','阮明',1,'学姐你好，我想报名加入咱们汉服社团可以吗？','xué jiě nǐ hǎo， wǒ xiǎng bào míng jiā rù zán men hàn fú shè tuán kě yǐ ma？','Chào chị, em muốn đăng ký tham gia câu lạc bộ Hán phục của chúng ta, được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_02','V336','学姐',2,'当然可以，先填一张信息登记表哦。','dāng rán kě yǐ， xiān tián yī zhāng xìn xī dēng jì biǎo ó。','Được chứ, em điền một tờ thông tin đăng ký trước nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_03','V336','阮明',3,'好的，我平时很喜欢中国传统服饰和文化。','hǎo de， wǒ píng shí hěn xǐ huān zhōng guó chuán tǒng fú shì hé wén huà。','Dạ vâng, em rất thích trang phục truyền thống và văn hóa Trung Quốc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_04','V336','学姐',4,'咱们每周有线下活动，不过本周活动名额满了。','zán men měi zhōu yǒu xiàn xià huó dòng， bù guò běn zhōu huó dòng míng é mǎn le。','Câu lạc bộ mình mỗi tuần đều có hoạt động ngoại tuyến, nhưng tuần này đã hết chỗ rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_05','V336','阮明',5,'啊？那我下周能正常参与活动吗？','a？ nà wǒ xià zhōu néng zhèng cháng cān yù huó dòng ma？','Ơ vậy ạ? Vậy tuần sau em có thể tham gia hoạt động bình thường không?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_06','V336','学姐',6,'没问题，下周名额会重新开放，记得准时来。','méi wèn tí， xià zhōu míng é huì chóng xīn kāi fàng， jì de zhǔn shí lái。','Không vấn đề gì, tuần sau sẽ mở lại chỗ trống, nhớ đến đúng giờ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_07','V336','阮明',7,'好，我会记好时间，麻烦学姐啦。','hǎo， wǒ huì jì hǎo shí jiān， má fán xué jiě la。','Dạ, em sẽ nhớ giờ, phiền chị nhiều ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT337','S112','Giải thích khi hiểu nhầm ý của bạn',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V337','SIT337','P1','suon_se','ban_chinh_thuc',NULL,'朋友产生隔阂后，中国人会主动沟通解释，厘清误会后不会一直记在心里。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_01','V337','阮明',1,'昨天那件事你是不是误会我了，我跟你解释一下吧。','zuó tiān nà jiàn shì nǐ shì bú shì wù huì wǒ le， wǒ gēn nǐ jiě shì yī xià ba。','Chuyện hôm qua chắc cậu hiểu lầm mình rồi, để mình giải thích cho cậu nghe nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_02','V337','李然',2,'我昨天确实有点生气，你说说是什么情况。','wǒ zuó tiān què shí yǒu diǎn shēng qì， nǐ shuō shuō shì shén me qíng kuàng。','Hôm qua mình đúng là có hơi giận thật, cậu kể xem rốt cuộc là chuyện gì đi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_03','V337','阮明',3,'我不是故意放你鸽子，是老师临时留我补作业呢。','wǒ bú shì gù yì fàng nǐ gē zi， shì lǎo shī lín shí liú wǒ bǔ zuò yè ne。','Mình không cố tình cho cậu leo cây đâu, tại thầy giữ mình lại bù bài tập đột xuất thôi.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_04','V337','李然',4,'原来是这样，我还以为你不想跟我出门。','yuán lái shì zhè yàng， wǒ hái yǐ wéi nǐ bù xiǎng gēn wǒ chū mén。','Ra là vậy à, mình còn tưởng cậu không muốn đi chơi với mình chứ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_05','V337','阮明',5,'怎么会，我一直很期待和你逛街的。','zěn me huì， wǒ yì zhí hěn qī dài hé nǐ guàng jiē de。','Sao có thể như vậy được, mình lúc nào cũng mong được đi dạo phố với cậu mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_06','V337','李然',6,'行，我明白啦，这件事就翻篇不提了。','xíng， wǒ míng bái la， zhè jiàn shì jiù fān piān bù tí le。','Được rồi, mình hiểu rồi, chuyện này coi như bỏ qua, không nhắc lại nữa nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_07','V337','阮明',7,'太好了，下次出门我提前跟你确认时间。','tài hǎo le， xià cì chū mén wǒ tí qián gēn nǐ què rèn shí jiān。','Tuyệt quá, lần sau đi đâu mình sẽ báo trước giờ giấc cho cậu xác nhận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT338','S112','Chúc mừng sinh nhật bạn cùng phòng',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V338','SIT338','P1','suon_se','tuy_y',NULL,'大学生宿舍室友常会合伙买蛋糕、礼物一起过生日，是宿舍常见暖心活动。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_01','V338','阮明',1,'张明，生日快乐！快拆开我们准备的蛋糕吧。','zhāng míng， shēng rì kuài lè！ kuài chāi kāi wǒ men zhǔn bèi de dàn gāo ba。','Trương Minh, chúc mừng sinh nhật cậu! Mau mở bánh kem tụi mình chuẩn bị ra đi.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_02','V338','张明',2,'哇，你们居然还记得我的生日，太惊喜了。','wa， nǐ men jū rán hái jì de wǒ de shēng rì， tài jīng xǐ le。','Ồ, không ngờ mấy cậu vẫn nhớ sinh nhật mình, bất ngờ quá đi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_03','V338','阮明',3,'我们悄悄凑钱买的，还有小礼物送给你呢。','wǒ men qiāo qiāo còu qián mǎi de， hái yǒu xiǎo lǐ wù sòng gěi nǐ ne。','Tụi mình lén góp tiền mua đó, còn có quà nhỏ tặng cậu nữa nè.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_04','V338','张明',4,'真的不用这么破费，有你们陪伴就足够啦。','zhēn de bù yòng zhè me pò fèi， yǒu nǐ men péi bàn jiù zú gòu la。','Thật sự không cần bày vẽ tốn kém vậy đâu, có mấy cậu ở bên là đủ rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_05','V338','阮明',5,'室友之间不用客气，赶紧许愿吹蜡烛哦。','shì yǒu zhī jiān bù yòng kè qì， gǎn jǐn xǔ yuàn chuī là zhú ó。','Bạn cùng phòng với nhau khỏi khách sáo, mau ước nguyện rồi thổi nến đi nào.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_06','V338','张明',6,'好，我许个愿，希望我们宿舍一直和睦。','hǎo， wǒ xǔ gè yuàn， xī wàng wǒ men sù shè yì zhí hé mù。','Được, để mình ước nguyện, mong sao phòng mình lúc nào cũng hòa thuận vui vẻ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_07','V338','阮明',7,'一定会的，咱们切蛋糕一起分享！','yí dìng huì de， zán men qiè dàn gāo yì qǐ fēn xiǎng！','Chắc chắn sẽ vậy mà, giờ mình cắt bánh cùng ăn chung thôi!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT339','S112','Hỏi mượn đồ dùng cá nhân từ bạn cùng lớp',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V339','SIT339','P1','twist','tuy_y',NULL,'向他人借私人物品需要主动询问，用完及时归还，很多人会用小饮品、零食答谢对方。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_01','V339','阮明',1,'菲菲，能不能借你的笔记本电脑用半小时啊？','fēi fēi， néng bù néng jiè nǐ de bǐ jì běn diàn nǎo yòng bàn xiǎo shí a？','Phi Phi ơi, cho mình mượn laptop của cậu xíu nửa tiếng được không?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_02','V339','刘菲',2,'不好意思，我电脑拿去图书馆充电了嘛。','bù hǎo yì sī， wǒ diàn nǎo ná qù tú shū guǎn chōng diàn le ma。','Ngại quá, máy tính của mình đem ra thư viện sạc pin rồi nè.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_03','V339','阮明',3,'这样啊，那你有多余的U盘借我拷贝文件吗？','zhè yàng a， nà nǐ yǒu duō yú de U pán jiè wǒ kǎo bèi wén jiàn ma？','Vậy à, thế cậu có USB dư không, cho mình mượn chép tài liệu với.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_04','V339','刘菲',4,'这个可以，我包里刚好有一个全新的。','zhè ge kě yǐ， wǒ bāo lǐ gāng hǎo yǒu yí gè quán xīn de。','Cái đó thì được, trong cặp mình đang có sẵn một cái còn mới nguyên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_05','V339','阮明',5,'太感谢了，用完我马上还给你，绝不弄丢。','tài gǎn xiè le， yòng wán wǒ mǎ shàng huán gěi nǐ， jué bù nòng diū。','Cảm ơn cậu nhiều lắm, dùng xong mình trả liền, không để mất đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_06','V339','刘菲',6,'没关系，你慢慢用，不用着急归还。','méi guān xì， nǐ màn màn yòng， bù yòng zháo jí guī huán。','Không sao đâu, cậu cứ từ từ dùng, không cần vội trả lại đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_07','V339','阮明',7,'好嘞，等下请你喝奶茶作为答谢。','hǎo lei， děng xià qǐng nǐ hē nǎi chá zuò wéi dá xiè。','Được luôn, lát nữa mình mời cậu ly trà sữa để cảm ơn nhé.','AM08') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT340','S112','Đề nghị đổi lịch hẹn vì bận đột xuất',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V340','SIT340','P1','suon_se','ban_chinh_thuc',NULL,'临时无法赴约，中国人会第一时间告知对方，主动协商新时间，避免对方空等。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_01','V340','阮明',1,'实在抱歉，我们下午约好逛书店得改时间了。','shí zài bào qiàn， wǒ men xià wǔ yuē hǎo guàng shū diàn dé gǎi shí jiān le。','Thật sự xin lỗi, buổi chiều mình hẹn đi nhà sách rồi nhưng phải đổi giờ mất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_02','V340','吴桐',2,'怎么了，是临时有突发事情吗？','zěn me le， shì lín shí yǒu tū fā shì qíng ma？','Sao vậy, có việc gì gấp phát sinh đột xuất à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_03','V340','阮明',3,'辅导员通知我去办公室提交留学材料呢。','fǔ dǎo yuán tōng zhī wǒ qù bàn gōng shì tí jiāo liú xué cái liào ne。','Cố vấn học tập thông báo mình lên văn phòng nộp hồ sơ du học đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_04','V340','吴桐',4,'没事，正事要紧，我们改到明天下午行吗？','méi shì， zhèng shì yào jǐn， wǒ men gǎi dào míng tiān xià wǔ xíng ma？','Không sao, việc chính quan trọng hơn, mình dời sang chiều mai được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_05','V340','阮明',5,'明天下午我全天有空，完全没问题的。','míng tiān xià wǔ wǒ quán tiān yǒu kòng， wán quán méi wèn tí de。','Chiều mai mình rảnh cả buổi, hoàn toàn không vấn đề gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_06','V340','吴桐',6,'那就定明天三点，咱们校门口碰面吧。','nà jiù dìng míng tiān sān diǎn， zán men xiào mén kǒu pèng miàn ba。','Vậy chốt ba giờ chiều mai, mình gặp nhau ở cổng trường nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_07','V340','阮明',7,'好，明天我提前十分钟在门口等你啦。','hǎo， míng tiān wǒ tí qián shí fēn zhōng zài mén kǒu děng nǐ la。','Được, mai mình sẽ đến sớm mười phút đợi cậu ở cổng nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT341','S114','Xin nghỉ một buổi sinh hoạt câu lạc bộ',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V341','SIT341','P1','suon_se','ban_chinh_thuc',NULL,'学生社团有事无法参与活动，需要提前向负责人报备请假，不能无故缺席。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_01','V341','阮明',1,'学姐，我想跟你请假，本周的社团活动没法参加了。','xué jiě， wǒ xiǎng gēn nǐ qǐng jià， běn zhōu de shè tuán huó dòng méi fǎ cān jiā le。','Chị ơi, em muốn xin phép nghỉ, tuần này em không tham gia sinh hoạt câu lạc bộ được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_02','V341','学姐',2,'可以，你是有什么重要的事情耽误了吗？','kě yǐ， nǐ shì yǒu shén me zhòng yào de shì qíng dān wù le ma？','Được thôi, em có việc gì quan trọng nên bị vướng đúng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_03','V341','阮明',3,'下周有汉语考试，我需要全天在家复习嘛。','xià zhōu yǒu hàn yǔ kǎo shì， wǒ xū yào quán tiān zài jiā fù xí ma。','Tuần sau em có bài thi tiếng Trung, em cần ở nhà ôn bài cả ngày ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_04','V341','学姐',4,'原来是备考，学习优先，我帮你登记请假。','yuán lái shì bèi kǎo， xué xí yōu xiān， wǒ bāng nǐ dēng jì qǐng jià。','Ra là chuẩn bị thi, học hành ưu tiên trước, để chị ghi sổ xin nghỉ cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_05','V341','阮明',5,'活动的任务我下周会主动补上，不会落下进度。','huó dòng de rèn wù wǒ xià zhōu huì zhǔ dòng bǔ shàng， bú huì là xià jìn dù。','Nhiệm vụ hoạt động tuần sau em sẽ chủ động bù lại, không để chậm tiến độ đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_06','V341','学姐',6,'不用着急，等你考完试再来参与就行。','bù yòng zháo jí， děng nǐ kǎo wán shì zài lái cān yù jiù xíng。','Không cần gấp đâu, đợi em thi xong rồi tham gia lại cũng được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_07','V341','阮明',7,'辛苦学姐体谅我啦，非常感谢。','xīn kǔ xué jiě tǐ liàng wǒ la， fēi cháng gǎn xiè。','Cảm ơn chị đã thông cảm cho em nhiều lắm ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT342','S112','Khen món ăn bạn Trung Quốc nấu, đáp lại khi được khen',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V342','SIT342','P1','suon_se','tuy_y',NULL,'品尝他人亲手做的饭菜，中国人会真诚夸赞，还会互相邀约交换拿手菜。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_01','V342','阮明',1,'你做的番茄炒蛋也太好吃了吧，味道超正宗！','nǐ zuò de fān qié chǎo dàn yě tài hǎo chī le ba， wèi dào chāo zhèng zōng！','Trứng chiên cà chua cậu làm ngon quá trời luôn, đúng vị chuẩn không cần chỉnh!','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_02','V342','小雅',2,'没有啦，就是简单家常菜，你喜欢就多吃点。','méi yǒu la， jiù shì jiǎn dān jiā cháng cài， nǐ xǐ huān jiù duō chī diǎn。','Có gì đâu, chỉ là món nhà làm đơn giản thôi, cậu thích thì ăn thêm nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_03','V342','阮明',3,'比校外餐馆做得还香，你厨艺也太好了啊。','bǐ xiào wài cān guǎn zuò dé hái xiāng， nǐ chú yì yě tài hǎo le a。','Còn ngon hơn cả mấy quán ăn ngoài trường, tay nghề nấu ăn của cậu đỉnh thật đấy.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_04','V342','小雅',4,'谢谢你夸奖，下次我教你一起做呢。','xiè xiè nǐ kuā jiǎng， xià cì wǒ jiāo nǐ yì qǐ zuò ne。','Cảm ơn cậu khen, lần sau mình chỉ cậu làm cùng luôn nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_05','V342','阮明',5,'那太好了，我还怕自己学不会。','nà tài hǎo le， wǒ hái pà zì jǐ xué bú huì。','Vậy thì tốt quá, mình còn sợ mình học không nổi chứ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_06','V342','小雅',6,'不难的，下次你做家乡菜给我尝尝吧。','bù nán de， xià cì nǐ zuò jiā xiāng cài gěi wǒ cháng cháng ba。','Không khó đâu, lần sau cậu làm món quê hương cho mình nếm thử nha.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_07','V342','阮明',7,'没问题，下次我带食材过来，一定露一手！','méi wèn tí， xià cì wǒ dài shí cái guò lái， yí dìng lòu yī shǒu！','Không thành vấn đề, lần sau mình mang nguyên liệu qua, nhất định trổ tài một phen!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT343','S115','Mua điện thoại mới, hỏi thông số',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V343','SIT343','P1','suon_se','tuy_y',NULL,'线下买电子产品，顾客可以自由询问全部参数，对比多款机型，店家不会催促下单。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_01','V343','阮明',1,'你好，这款新款手机内存和电池容量是多少啊？','nǐ hǎo， zhè kuǎn xīn kuǎn shǒu jī nèi cún hé diàn chí róng liàng shì duō shǎo a？','Chào bạn, chiếc điện thoại đời mới này dung lượng bộ nhớ và pin bao nhiêu vậy?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_02','V343','销售员',2,'这款手机256G内存，电池续航一整天没问题。','zhè kuǎn shǒu jī 256G nèi cún， diàn chí xù háng yī zhěng tiān méi wèn tí。','Chiếc này bộ nhớ 256G, pin dùng cả ngày thoải mái không lo hết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_03','V343','阮明',3,'拍照像素高吗？我平时很喜欢出门拍照呢。','pāi zhào xiàng sù gāo ma？ wǒ píng shí hěn xǐ huān chū mén pāi zhào ne。','Camera có độ phân giải cao không? Mình hay đi đâu cũng chụp ảnh lắm.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_04','V343','销售员',4,'后置五千万像素，夜景拍摄效果特别清晰。','hòu zhì wǔ qiān wàn xiàng sù， yè jǐng pāi shè xiào guǒ tè bié qīng xī。','Camera sau 50 triệu điểm ảnh, chụp cảnh đêm nét căng luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_05','V343','阮明',5,'那处理器运行会不会卡顿，适合学习软件吗？','nà chǔ lǐ qì yùn xíng huì bú huì kǎ dùn， shì hé xué xí ruǎn jiàn ma？','Vậy chip xử lý chạy có giật lag không, có hợp để học phần mềm không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_06','V343','销售员',6,'配置足够流畅运行各类软件，学生用很合适。','pèi zhì zú gòu liú chàng yùn xíng gè lèi ruǎn jiàn， xué shēng yòng hěn hé shì。','Cấu hình chạy mượt đủ mọi phần mềm, dùng cho sinh viên rất hợp đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_07','V343','阮明',7,'行，那我再对比一下另一款，等下再来找你。','xíng， nà wǒ zài duì bǐ yī xià lìng yī kuǎn， děng xià zài lái zhǎo nǐ。','Được, để mình so sánh thêm với mẫu kia, lát nữa quay lại tìm bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT344','S115','Mang điện thoại đi sửa màn hình vỡ',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V344','SIT344','P1','twist','ban_chinh_thuc',NULL,'手机维修更换配件分原装和平价配件，店家会主动区分报价，配件缺货会告知顾客取机时间。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_01','V344','阮明',1,'师傅，我的手机屏幕摔碎了，能帮忙更换吗？','shī fù， wǒ de shǒu jī píng mù shuāi suì le， néng bāng máng gēng huàn ma？','Anh ơi, màn hình điện thoại em bị vỡ rồi, giúp em thay được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_02','V344','维修师傅',2,'可以，先看看型号，原装屏幕价格贵一点哈。','kě yǐ， xiān kàn kàn xíng hào， yuán zhuāng píng mù jià gé guì yì diǎn hā。','Được, để xem qua đời máy đã, màn hình chính hãng giá hơi cao chút nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_03','V344','阮明',3,'原装的大概多少钱，维修需要等多久呢？','yuán zhuāng de dà gài duō shǎo qián， wéi xiū xū yào děng duō jiǔ ne？','Màn hình chính hãng khoảng bao nhiêu tiền vậy anh, sửa mất bao lâu ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_04','V344','维修师傅',4,'三百五十元，可惜现在店里没有现货屏幕。','sān bǎi wǔ shí yuán， kě xī xiàn zài diàn lǐ méi yǒu xiàn huò píng mù。','Ba trăm năm mươi tệ, tiếc là hiện tại cửa hàng không có sẵn màn hình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_05','V344','阮明',5,'啊？那什么时候能到货，我手机每天都要用。','a？ nà shén me shí hòu néng dào huò， wǒ shǒu jī měi tiān dōu yào yòng。','Hả? Vậy bao giờ mới có hàng, điện thoại em ngày nào cũng phải dùng.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_06','V344','维修师傅',6,'明天中午到货，你明天下午过来取就行。','míng tiān zhōng wǔ dào huò， nǐ míng tiān xià wǔ guò lái qǔ jiù xíng。','Trưa mai hàng về, em chiều mai qua lấy là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_07','V344','阮明',7,'好，我明天准时过来，麻烦师傅预留屏幕。','hǎo， wǒ míng tiān zhǔn shí guò lái， má fán shī fù yù liú píng mù。','Vâng, mai em qua đúng giờ, phiền anh giữ màn hình lại giúp em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT345','S116','Mua laptop, hỏi bảo hành',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V345','SIT345','P1','suon_se','ban_chinh_thuc',NULL,'国内数码产品均提供全国联保服务，门店会清晰告知保修时长、售后范围。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_01','V345','阮明',1,'这款笔记本适合留学生写论文、做PPT吗？','zhè kuǎn bǐ jì běn shì hé liú xué shēng xiě lùn wén、 zuò PPT ma？','Chiếc laptop này có phù hợp cho du học sinh viết luận văn, làm PPT không anh/chị?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_02','V345','导购',2,'完全适配，轻薄便携，性能足够日常学习的。','wán quán shì pèi， qīng bó biàn xié， xìng néng zú gòu rì cháng xué xí de。','Hoàn toàn phù hợp luôn, máy mỏng nhẹ dễ mang theo, cấu hình đủ dùng cho việc học hàng ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_03','V345','阮明',3,'那整机官方保修时长是多久呀？','nà zhěng jī guān fāng bǎo xiū shí cháng shì duō jiǔ ya？','Vậy thời hạn bảo hành chính hãng của nguyên bộ máy là bao lâu vậy ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_04','V345','导购',4,'基础全国联保一年，加钱可以升级到三年哦。','jī chǔ quán guó lián bǎo yī nián， jiā qián kě yǐ shēng jí dào sān nián ó。','Bảo hành toàn quốc cơ bản là một năm, nếu trả thêm phí thì có thể nâng lên ba năm nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_05','V345','阮明',5,'保修期内系统故障能免费上门维修吗？','bǎo xiū qī nèi xì tǒng gù zhàng néng miǎn fèi shàng mén wéi xiū ma？','Trong thời gian bảo hành, nếu máy gặp lỗi hệ thống thì có được sửa tận nơi miễn phí không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_06','V345','导购',6,'市区范围内可以免费上门，超出范围需要送店。','shì qū fàn wéi nèi kě yǐ miǎn fèi shàng mén， chāo chū fàn wéi xū yào sòng diàn。','Trong nội thành thì được sửa tận nơi miễn phí, còn ngoài phạm vi đó thì phải mang máy ra cửa hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_07','V345','阮明',7,'了解了，我考虑一下，晚点过来付款吧。','liǎo jiě le， wǒ kǎo lǜ yī xià， wǎn diǎn guò lái fù kuǎn ba。','Em hiểu rồi, để em suy nghĩ thêm, lát nữa em quay lại thanh toán nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT346','S117','Đăng ký lắp Internet cho phòng trọ',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V346','SIT346','P1','twist','ban_chinh_thuc',NULL,'租房办理宽带需要核验房屋地址，小区宽带端口有限，满员只能排队等待新端口。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_01','V346','阮明',1,'你好，我租的单间想办理宽带安装业务。','nǐ hǎo， wǒ zū de dān jiān xiǎng bàn lǐ kuān dài ān zhuāng yè wù。','Chào anh/chị, phòng trọ em thuê muốn đăng ký lắp mạng cáp quang ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_02','V346','客服',2,'您好，请提供详细地址，我查询线路覆盖情况。','nín hǎo， qǐng tí gōng xiáng xì dì zhǐ， wǒ chá xún xiàn lù fù gài qíng kuàng。','Chào bạn, bạn cho mình xin địa chỉ chi tiết để mình kiểm tra xem khu vực đó có phủ sóng đường truyền không nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_03','V346','阮明',3,'地址是大学周边小区3栋502室，麻烦查一下。','dì zhǐ shì dà xué zhōu biān xiǎo qū 3 dòng 502 shì， má fán chá yī xià。','Địa chỉ là khu chung cư quanh trường đại học, tòa 3, phòng 502, phiền anh/chị kiểm tra giúp em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_04','V346','客服',4,'不好意思，您小区本周宽带端口已经全部用完了嘛。','bù hǎo yì sī， nín xiǎo qū běn zhōu kuān dài duān kǒu yǐ jīng quán bù yòng wán le ma。','Xin lỗi bạn nhé, khu chung cư của bạn tuần này các cổng mạng đã dùng hết sạch rồi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_05','V346','阮明',5,'这样啊，那下一批端口什么时候开放呢？','zhè yàng a， nà xià yī pī duān kǒu shén me shí hòu kāi fàng ne？','Vậy à, thế đợt cổng mạng tiếp theo khi nào mới mở vậy ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_06','V346','客服',6,'三天后重新放号，到时候我可以提醒您预约。','sān tiān hòu chóng xīn fàng hào， dào shí hòu wǒ kě yǐ tí xǐng nín yù yuē。','Ba ngày nữa sẽ mở đợt số mới, đến lúc đó mình có thể nhắc bạn đăng ký trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_07','V346','阮明',7,'好，那麻烦三天后联系我，辛苦你啦。','hǎo， nà má fán sān tiān hòu lián xì wǒ， xīn kǔ nǐ la。','Vâng, vậy phiền anh/chị ba ngày nữa liên hệ lại với em nhé, cảm ơn anh/chị nhiều ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT347','S115','Chuyển dữ liệu sang điện thoại mới',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V347','SIT347','P1','suon_se','tuy_y',NULL,'国产手机自带一键换机功能，年轻人大多会互相帮忙操作数据迁移。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_01','V347','阮明',1,'我刚换了新手机，不知道怎么转移旧手机数据啊。','wǒ gāng huàn le xīn shǒu jī， bù zhī dào zěn me zhuǎn yí jiù shǒu jī shù jù a。','Tớ mới đổi điện thoại mới, chẳng biết chuyển dữ liệu từ máy cũ sang thế nào cả.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_02','V347','小杨',2,'很简单，手机自带换机软件，跟着步骤操作就行啦。','hěn jiǎn dān， shǒu jī zì dài huàn jī ruǎn jiàn， gēn zhe bù zhòu cāo zuò jiù xíng la。','Đơn giản lắm, điện thoại có sẵn phần mềm chuyển máy, cứ làm theo các bước là được thôi mà.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_03','V347','阮明',3,'聊天记录、照片和文件都能完整复制过去吗？','liáo tiān jì lù、 zhào piān hé wén jiàn dōu néng wán zhěng fù zhì guò qù ma？','Tin nhắn, ảnh với file đều có thể copy sang nguyên vẹn hết à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_04','V347','小杨',4,'全部可以，就是两台手机都要连接同一个WiFi呢。','quán bù kě yǐ， jiù shì liǎng tái shǒu jī dōu yào lián jiē tóng yī gè WiFi ne。','Tất tần tật đều được, chỉ cần hai máy cùng kết nối chung một wifi thôi đó.','AM04') ON CONFLICT DO NOTHING;
